1	"use client";
2	
3	import { useEffect, useRef, useState, useTransition } from "react";
4	import { submitBuild, approveBuild, rejectBuild } from "@/lib/actions-claude";
5	
6	type ServerOption = { id: string; hostname: string };
7	type BuildState = { status: string; steps: number; log: string; plan?: string | null };
8	type PlanStep = { cmd: string; intent?: string };
9	
10	const EXAMPLES = [
11	  "Install and configure nginx serving a simple landing page over HTTP.",
12	  "Set up Node.js LTS, PM2, and a UFW firewall allowing only SSH and HTTP/HTTPS.",
13	  "Install Docker and run a Postgres 16 container with a persistent volume.",
14	];
15	
16	const TERMINAL = new Set(["DONE", "FAILED"]);
17	
18	function parsePlan(raw?: string | null): PlanStep[] {
19	  if (!raw) return [];
20	  try {
21	    const p = JSON.parse(raw);
22	    if (Array.isArray(p)) {
23	      return p
24	        .map((s) => (typeof s === "string" ? { cmd: s } : { cmd: String(s?.cmd ?? ""), intent: s?.intent }))
25	        .filter((s) => s.cmd);
26	    }
27	  } catch {
28	    /* ignore */
29	  }
30	  return [];
31	}
32	
33	export function ClaudeBuilder({ servers }: { servers: ServerOption[] }) {
34	  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
35	  const [prompt, setPrompt] = useState("");
36	  const [error, setError] = useState<string | null>(null);
37	  const [buildId, setBuildId] = useState<string | null>(null);
38	  const [state, setState] = useState<BuildState | null>(null);
39	  const [pending, startTransition] = useTransition();
40	  const logRef = useRef<HTMLPreElement>(null);
41	
42	  // Poll the build status while a build is active (until it reaches DONE/FAILED).
43	  useEffect(() => {
44	    if (!buildId) return;
45	    let alive = true;
46	    let timer: ReturnType<typeof setTimeout>;
47	
48	    const tick = async () => {
49	      try {
50	        const res = await fetch(`/api/claude/${buildId}`, { cache: "no-store" });
51	        if (res.ok) {
52	          const data = (await res.json()) as BuildState;
53	          if (alive) setState(data);
54	          if (data.status && TERMINAL.has(data.status)) return; // stop polling
55	        }
56	      } catch {
57	        /* transient — keep polling */
58	      }
59	      if (alive) timer = setTimeout(tick, 2000);
60	    };
61	    void tick();
62	    return () => {
63	      alive = false;
64	      clearTimeout(timer);
65	    };
66	  }, [buildId]);
67	
68	  // Keep the log scrolled to the bottom as it streams.
69	  useEffect(() => {
70	    if (logRef.current) logRef.current.scrollTop = logRef.current.scrollHeight;
71	  }, [state?.log]);
72	
73	  const status = state?.status ?? null;
74	  const inProgress = Boolean(buildId) && !(status && TERMINAL.has(status));
75	  const awaitingApproval = status === "AWAITING_APPROVAL";
76	  const planning = status === "QUEUED" || status === "PLANNING";
77	  const executing = status === "RUNNING";
78	  const plan = parsePlan(state?.plan);
79	
80	  const onSubmit = (e: React.FormEvent) => {
81	    e.preventDefault();
82	    setError(null);
83	    startTransition(async () => {
84	      const res = await submitBuild(serverId, prompt);
85	      if (res.error) {
86	        setError(res.error);
87	        return;
88	      }
89	      if (res.buildId) {
90	        setBuildId(res.buildId);
91	        setState({ status: "QUEUED", steps: 0, log: "", plan: null });
92	      }
93	    });
94	  };
95	
96	  const onApprove = () => {
97	    if (!buildId) return;
98	    setError(null);
99	    startTransition(async () => {
100	      const res = await approveBuild(buildId);
101	      if (res.error) {
102	        setError(res.error);
103	        return;
104	      }
105	      // Optimistically flip to QUEUED; polling will pick up RUNNING → DONE.
106	      setState((s) => (s ? { ...s, status: "QUEUED" } : s));
107	    });
108	  };
109	
110	  const onReject = () => {
111	    if (!buildId) return;
112	    setError(null);
113	    startTransition(async () => {
114	      const res = await rejectBuild(buildId);
115	      if (res.error) {
116	        setError(res.error);
117	        return;
118	      }
119	      setState((s) => (s ? { ...s, status: "FAILED" } : s));
120	    });
121	  };
122	
123	  const reset = () => {
124	    setBuildId(null);
125	    setState(null);
126	    setPrompt("");
127	    setError(null);
128	  };
129	
130	  const statusTone =
131	    status === "DONE"
132	      ? "border-emerald-500/40 bg-emerald-500/10 text-emerald-300"
133	      : status === "FAILED"
134	      ? "border-red-500/40 bg-red-500/10 text-red-300"
135	      : status === "AWAITING_APPROVAL"
136	      ? "border-sky-500/40 bg-sky-500/10 text-sky-300"
137	      : "border-amber-500/40 bg-amber-500/10 text-amber-300";
138	
139	  return (
140	    <div className="space-y-6">
141	      <form onSubmit={onSubmit} className="card space-y-4 p-5">
142	        <div>
143	          <label className="mb-1.5 block text-sm font-medium text-slate-300">Server</label>
144	          <select
145	            className="input"
146	            value={serverId}
147	            onChange={(e) => setServerId(e.target.value)}
148	            disabled={inProgress || pending}
149	          >
150	            {servers.map((s) => (
151	              <option key={s.id} value={s.id}>
152	                {s.hostname}
153	              </option>
154	            ))}
155	          </select>
156	        </div>
157	
158	        <div>
159	          <label className="mb-1.5 block text-sm font-medium text-slate-300">
160	            What should Claude build?
161	          </label>
162	          <textarea
163	            className="input min-h-[110px] resize-y font-normal"
164	            placeholder="e.g. Install and configure a Node.js app served behind nginx with a firewall."
165	            value={prompt}
166	            onChange={(e) => setPrompt(e.target.value)}
167	            maxLength={2000}
168	            disabled={inProgress || pending}
169	          />
170	          <div className="mt-2 flex flex-wrap gap-2">
171	            {EXAMPLES.map((ex) => (
172	              <button
173	                key={ex}
174	                type="button"
175	                onClick={() => setPrompt(ex)}
176	                disabled={inProgress || pending}
177	                className="rounded-full border border-white/10 bg-white/[0.04] px-3 py-1 text-xs text-slate-400 hover:text-slate-200 disabled:opacity-50"
178	              >
179	                {ex.length > 46 ? ex.slice(0, 46) + "…" : ex}
180	              </button>
181	            ))}
182	          </div>
183	        </div>
184	
185	        {error && <p className="text-sm text-red-300">{error}</p>}
186	
187	        <div className="flex items-center gap-3">
188	          <button
189	            type="submit"
190	            className="btn-primary"
191	            disabled={inProgress || pending || !serverId || prompt.trim().length < 8}
192	          >
193	            {pending && !buildId ? "Starting…" : inProgress ? "In progress…" : "Plan with Claude"}
194	          </button>
195	          {buildId && !inProgress && (
196	            <button type="button" onClick={reset} className="btn-secondary">
197	              New build
198	            </button>
199	          )}
200	        </div>
201	        <p className="text-xs text-slate-500">
202	          Claude first proposes an ordered list of shell commands. Nothing runs on your server until you
203	          review and <span className="font-medium text-slate-400">Approve</span> the plan. Up to 20
204	          commands then run over SSH; you are responsible for the changes made to your server.
205	        </p>
206	      </form>
207	
208	      {state && (
209	        <div className="card space-y-4 p-5">
210	          <div className="flex flex-wrap items-center justify-between gap-3">
211	            <div className="flex items-center gap-3">
212	              <span
213	                className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium ${statusTone}`}
214	              >
215	                {inProgress && !awaitingApproval && (
216	                  <span className="mr-2 h-1.5 w-1.5 animate-pulse rounded-full bg-current" />
217	                )}
218	                {status ? status.toLowerCase().replace(/_/g, " ") : "…"}
219	              </span>
220	              {executing && <span className="text-xs text-slate-500">step {state.steps}</span>}
221	            </div>
222	          </div>
223	
224	          {planning && (
225	            <p className="text-sm text-slate-400">
226	              Claude is drafting a plan of commands for this goal…
227	            </p>
228	          )}
229	
230	          {awaitingApproval && plan.length > 0 && (
231	            <div className="space-y-4">
232	              <div>
233	                <h3 className="text-sm font-semibold text-slate-200">Proposed plan</h3>
234	                <p className="mt-1 text-xs text-slate-500">
235	                  Review these {plan.length} command(s). They only run if you approve.
236	                </p>
237	              </div>
238	              <ol className="space-y-2">
239	                {plan.map((step, i) => (
240	                  <li
241	                    key={i}
242	                    className="rounded-xl border border-white/[0.08] bg-navy-950/60 p-3"
243	                  >
244	                    <code className="block whitespace-pre-wrap break-words font-mono text-xs text-slate-200">
245	                      $ {step.cmd}
246	                    </code>
247	                    {step.intent && (
248	                      <p className="mt-1.5 text-xs text-slate-500">{step.intent}</p>
249	                    )}
250	                  </li>
251	                ))}
252	              </ol>
253	              <div className="flex items-center gap-3">
254	                <button type="button" onClick={onApprove} disabled={pending} className="btn-primary">
255	                  {pending ? "Working…" : "Approve & run"}
256	                </button>
257	                <button type="button" onClick={onReject} disabled={pending} className="btn-danger">
258	                  Reject
259	                </button>
260	              </div>
261	            </div>
262	          )}
263	
264	          {(executing || (status && TERMINAL.has(status))) && (
265	            <pre
266	              ref={logRef}
267	              className="max-h-[440px] overflow-auto whitespace-pre-wrap break-words rounded-xl border border-white/[0.08] bg-navy-950/80 p-4 font-mono text-xs leading-relaxed text-slate-300"
268	            >
269	              {state.log || (executing ? "Waiting for the worker to pick up the job…" : "No output.")}
270	            </pre>
271	          )}
272	        </div>
273	      )}
274	    </div>
275	  );
276	}
