1	"use server";
2	
3	// Server actions for the "Build with Claude AI" feature.
4	// Only async functions are exported (Next.js "use server" constraint).
5	//
6	// Flow: submitBuild -> (worker plans) -> AWAITING_APPROVAL
7	//       -> approveBuild (owner) -> (worker executes) -> DONE/FAILED
8	//       -> rejectBuild (owner) -> FAILED. Nothing runs on the server until the
9	//       owner approves the proposed command plan.
10	
11	import { revalidatePath } from "next/cache";
12	import { db } from "./db";
13	import { requireUser } from "./auth";
14	import { effectiveKeyFor } from "./anthropic";
15	import { serverRootPassword } from "./sftp";
16	import { getSettingBool } from "./settings";
17	
18	const MAX_PROMPT_CHARS = 2000;
19	const MIN_PROMPT_CHARS = 8;
20	// Cap how many builds a user may have in flight, and how many they can start in
21	// a short window, to keep API + SSH usage sane.
22	const MAX_ACTIVE_BUILDS_PER_USER = 3;
23	const RATE_WINDOW_MS = 60_000;
24	const MAX_BUILDS_PER_WINDOW = 5;
25	
26	// Statuses that mean a build is not yet finished (planning, awaiting approval,
27	// queued, or executing) — used for in-flight accounting.
28	const ACTIVE_STATUSES = ["QUEUED", "PLANNING", "AWAITING_APPROVAL", "RUNNING"] as const;
29	
30	export async function submitBuild(
31	  serverId: string,
32	  prompt: string
33	): Promise<{ error?: string; buildId?: string }> {
34	  const user = await requireUser();
35	
36	  // Feature flag: "Build with Claude" can be switched off platform-wide.
37	  if (!(await getSettingBool("feature_claude_builder", true))) {
38	    return { error: "Build with Claude is currently unavailable." };
39	  }
40	
41	  const clean = (prompt ?? "").trim();
42	  if (clean.length < MIN_PROMPT_CHARS) {
43	    return { error: "Please describe what you'd like Claude to build (a sentence or two)." };
44	  }
45	  if (clean.length > MAX_PROMPT_CHARS) {
46	    return { error: `Prompt is too long (max ${MAX_PROMPT_CHARS} characters).` };
47	  }
48	
49	  // BYOK gate: the owner must have an effective key (their own, or a platform fallback).
50	  const owner = await db.user.findUnique({
51	    where: { id: user.id },
52	    select: { anthropicKeyEnc: true },
53	  });
54	  if (!effectiveKeyFor(owner)) {
55	    return { error: "Add your Anthropic API key in Settings to use Build with AI." };
56	  }
57	
58	  // Ownership: the server must belong to this user.
59	  const server = await db.server.findFirst({ where: { id: serverId, userId: user.id } });
60	  if (!server) return { error: "Server not found." };
61	  if (server.status !== "RUNNING") {
62	    return { error: "The server must be running to build on it." };
63	  }
64	  if (!server.ipAddress || !serverRootPassword(server)) {
65	    return { error: "This server isn't reachable yet — try again once it finishes provisioning." };
66	  }
67	
68	  // Rate sanity.
69	  const active = await db.claudeBuild.count({
70	    where: { userId: user.id, status: { in: [...ACTIVE_STATUSES] } },
71	  });
72	  if (active >= MAX_ACTIVE_BUILDS_PER_USER) {
73	    return { error: "You already have builds in progress. Wait for them to finish before starting another." };
74	  }
75	  const recent = await db.claudeBuild.count({
76	    where: { userId: user.id, createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) } },
77	  });
78	  if (recent >= MAX_BUILDS_PER_WINDOW) {
79	    return { error: "Too many builds started just now — please wait a minute and try again." };
80	  }
81	  // One in-flight build per server keeps the SSH session serialized.
82	  const serverBusy = await db.claudeBuild.count({
83	    where: { serverId, status: { in: [...ACTIVE_STATUSES] } },
84	  });
85	  if (serverBusy > 0) {
86	    return { error: "A build is already in progress on this server." };
87	  }
88	
89	  const build = await db.claudeBuild.create({
90	    data: { userId: user.id, serverId, prompt: clean, status: "QUEUED", approved: false },
91	  });
92	
93	  // Enqueue the worker job; the handler reads the build via payload.buildId.
94	  // Because approved=false, the worker will PLAN (not execute).
95	  await db.job.create({
96	    data: { type: "CLAUDE_BUILD", serverId, payload: { buildId: build.id } },
97	  });
98	
99	  await db.auditLog
100	    .create({
101	      data: { userId: user.id, action: "server.claude_build", detail: `${serverId} ${build.id}` },
102	    })
103	    .catch(() => {});
104	
105	  revalidatePath("/dashboard/build");
106	  return { buildId: build.id };
107	}
108	
109	/**
110	 * Owner approves the proposed plan. Marks it approved and enqueues a second
111	 * CLAUDE_BUILD job; the worker then executes the stored plan over SSH.
112	 */
113	export async function approveBuild(id: string): Promise<{ error?: string; ok?: boolean }> {
114	  const user = await requireUser();
115	
116	  const build = await db.claudeBuild.findFirst({ where: { id, userId: user.id } });
117	  if (!build) return { error: "Build not found." };
118	  if (build.status !== "AWAITING_APPROVAL") {
119	    return { error: "This build isn't awaiting approval." };
120	  }
121	  if (!build.plan) {
122	    return { error: "This build has no plan to approve." };
123	  }
124	
125	  // Compare-and-swap off AWAITING_APPROVAL, then enqueue in the same
126	  // transaction. The status read above is a snapshot: two overlapping approvals
127	  // (a double-click, an impatient retry) both saw AWAITING_APPROVAL and both
128	  // queued a CLAUDE_BUILD job, so the AI's command plan — arbitrary shell run
129	  // over SSH as root on the customer's server — was executed TWICE. Almost none
130	  // of those plans are idempotent. Only the swap that flips the row wins.
131	  const claimed = await db.claudeBuild.updateMany({
132	    where: { id, userId: user.id, status: "AWAITING_APPROVAL" },
133	    data: { approved: true, status: "QUEUED" },
134	  });
135	  if (claimed.count === 0) {
136	    return { error: "This build was already approved — refresh the page to watch it run." };
137	  }
138	
139	  await db.job.create({
140	    data: { type: "CLAUDE_BUILD", serverId: build.serverId, payload: { buildId: build.id } },
141	  });
142	
143	  await db.auditLog
144	    .create({
145	      data: { userId: user.id, action: "server.claude_build_approve", detail: `${build.serverId} ${id}` },
146	    })
147	    .catch(() => {});
148	
149	  revalidatePath("/dashboard/build");
150	  return { ok: true };
151	}
152	
153	/** Owner rejects the proposed plan. Marks the build FAILED; nothing runs. */
154	export async function rejectBuild(id: string): Promise<{ error?: string; ok?: boolean }> {
155	  const user = await requireUser();
156	
157	  const build = await db.claudeBuild.findFirst({ where: { id, userId: user.id } });
158	  if (!build) return { error: "Build not found." };
159	  if (build.status !== "AWAITING_APPROVAL") {
160	    return { error: "This build isn't awaiting approval." };
161	  }
162	
163	  // Same compare-and-swap as approveBuild — a reject that races an approve must
164	  // not be able to mark a build FAILED after it has already been queued to run.
165	  const claimed = await db.claudeBuild.updateMany({
166	    where: { id, userId: user.id, status: "AWAITING_APPROVAL" },
167	    data: { status: "FAILED", log: (build.log ?? "") + "\n[nxeon] Plan rejected by owner — nothing was run.\n" },
168	  });
169	  if (claimed.count === 0) {
170	    return { error: "This build is no longer awaiting approval — refresh the page to see its current state." };
171	  }
172	
173	  await db.auditLog
174	    .create({
175	      data: { userId: user.id, action: "server.claude_build_reject", detail: `${build.serverId} ${id}` },
176	    })
177	    .catch(() => {});
178	
179	  revalidatePath("/dashboard/build");
180	  return { ok: true };
181	}
182	
183	export async function listBuilds(serverId?: string) {
184	  const user = await requireUser();
185	  return db.claudeBuild.findMany({
186	    where: { userId: user.id, ...(serverId ? { serverId } : {}) },
187	    orderBy: { createdAt: "desc" },
188	    take: 20,
189	    include: { server: { select: { hostname: true } } },
190	  });
191	}
