1	"use server";
2	
3	// Server actions for connecting/disconnecting a customer's own Anthropic API
4	// key (BYOK). Only async functions are exported (Next.js "use server" rule).
5	// The stored key is AES-256-GCM encrypted at rest and NEVER returned to the
6	// client — callers can only learn whether a key is connected, not its value.
7	
8	import { revalidatePath } from "next/cache";
9	import { db } from "./db";
10	import { requireUser } from "./auth";
11	import { encryptSecret } from "./crypto-box";
12	
13	// Anthropic keys look like `sk-ant-api03-...` — a stable, recognizable prefix
14	// followed by an opaque token. We validate shape only (never call the API here).
15	const ANTHROPIC_KEY_RE = /^sk-ant-[A-Za-z0-9_-]{20,}$/;
16	
17	export async function connectAnthropicKey(key: string): Promise<{ error?: string; ok?: boolean }> {
18	  const user = await requireUser();
19	
20	  const clean = (key ?? "").trim();
21	  if (!clean) {
22	    return { error: "Please paste your Anthropic API key." };
23	  }
24	  if (!ANTHROPIC_KEY_RE.test(clean)) {
25	    return { error: 'That doesn’t look like an Anthropic API key — it should start with "sk-ant-".' };
26	  }
27	
28	  await db.user.update({
29	    where: { id: user.id },
30	    data: { anthropicKeyEnc: encryptSecret(clean) },
31	  });
32	
33	  await db.auditLog
34	    .create({ data: { userId: user.id, action: "user.anthropic_key_connect", detail: "connected" } })
35	    .catch(() => {});
36	
37	  // The key is managed in Settings; the planner reads it to decide if it can run.
38	  revalidatePath("/dashboard/settings");
39	  revalidatePath("/dashboard/build");
40	  return { ok: true };
41	}
42	
43	export async function disconnectAnthropicKey(): Promise<{ ok: boolean }> {
44	  const user = await requireUser();
45	
46	  await db.user.update({
47	    where: { id: user.id },
48	    data: { anthropicKeyEnc: null },
49	  });
50	
51	  await db.auditLog
52	    .create({ data: { userId: user.id, action: "user.anthropic_key_disconnect", detail: "disconnected" } })
53	    .catch(() => {});
54	
55	  // The key is managed in Settings; the planner reads it to decide if it can run.
56	  revalidatePath("/dashboard/settings");
57	  revalidatePath("/dashboard/build");
58	  return { ok: true };
59	}
60	
61	/** Whether the current user has a stored key. Returns a boolean only — never the key. */
62	export async function hasAnthropicKey(): Promise<boolean> {
63	  const user = await requireUser();
64	  const u = await db.user.findUnique({
65	    where: { id: user.id },
66	    select: { anthropicKeyEnc: true },
67	  });
68	  return Boolean(u?.anthropicKeyEnc);
69	}
