1	import { requireUser } from "@/lib/auth";
2	import { db } from "@/lib/db";
3	import { ClaudeCodeHub } from "@/components/customer/claude-code/ClaudeCodeHub";
4	
5	export const dynamic = "force-dynamic";
6	export const metadata = { title: "Build with AI" };
7	
8	export default async function ClaudeCodePage() {
9	  const user = await requireUser();
10	
11	  const servers = await db.server.findMany({
12	    where: { userId: user.id, status: "RUNNING" },
13	    select: {
14	      id: true,
15	      hostname: true,
16	      sshPort: true,
17	      dedicatedIp: { select: { address: true } },
18	    },
19	    orderBy: { createdAt: "desc" },
20	  });
21	
22	  const publicIp = process.env.PUBLIC_IP || "YOUR_SERVER_IP";
23	  const list = servers.map((s) => {
24	    const ip = s.dedicatedIp?.address;
25	    const connect = ip ? `ssh root@${ip}` : `ssh -p ${s.sshPort ?? 22} root@${publicIp}`;
26	    return { id: s.id, hostname: s.hostname, connect };
27	  });
28	
29	  return <ClaudeCodeHub servers={list} />;
30	}
