322	      const live = liveRef.current.get(id);
323	      if (!live) return;
324	      try {
325	        live.ro?.disconnect();
326	      } catch {
327	        /* ignore */
328	      }
329	      live.ro = null;
330	      try {
331	        live.ws?.close();
332	      } catch {
333	        /* ignore */
334	      }
335	      live.ws = null;
336	      try {
337	        live.term?.dispose();
338	      } catch {
339	        /* ignore */
340	      }
341	      live.term = null;
342	      live.fit = null;
343	      live.starting = false;
