49	/** Every `export async function NAME` in a (comment-stripped) module. */
50	function exportedActions(src: string): string[] {
51	  return [...src.matchAll(/export\s+async\s+function\s+([A-Za-z0-9_$]+)\s*\(/g)].map((m) => m[1]);
