58	 * allowed to unbalance the count.
59	 */
60	function bodyOf(src: string, name: string): string {
61	  const decl = new RegExp(`export\\s+async\\s+function\\s+${name}\\s*\\(`).exec(src);
62	  assert.ok(decl, `expected to find an exported action named ${name}`);
63	
64	  // Walk the parameter list to its closing paren, then find the body's opening
65	  // brace. The brace cannot simply be "the next `{`": a return annotation like
66	  // `Promise<{ error?: string }>` puts one in the way, and matching from there
67	  // returns the TYPE instead of the body — which silently makes every assertion
68	  // about that function vacuous. So skip braces that sit inside `<…>`.
