94	  let depth = 0;
95	  quote = null;
96	  for (; i < src.length; i++) {
97	    const c = src[i];
98	    if (quote) {
99	      if (c === "\\") {
100	        i++;
101	        continue;
102	      }
103	      if (c === quote) quote = null;
104	      continue;
105	    }
106	    if (c === '"' || c === "'" || c === "`") {
107	      quote = c;
