// Pure, dependency-free logic for the Build Studio multi-console workspace.
//
// This module has NO "use server" directive and NO side effects, so its pure
// helpers can be unit-tested directly and imported by both the server action
// (lib/actions-claude-console.ts) and the client UI. Anything that touches the
// database, the Anthropic API, or SSH lives in the action, not here.
//
// What lives here:
//   - the console state machine (build status -> a coarse UI phase)
//   - the mirror-mode fan-out (one prompt -> N independent build requests)
//   - multimodal image-part assembly (pasted data URLs -> Anthropic image blocks)
// Each is covered by test/build-studio.test.ts.

/** How many AI build consoles a workspace may hold at once. */
export const MAX_CONSOLES = 6;

/** Mirror mode fans a single prompt across this many consoles (inclusive). */
export const MIRROR_MIN = 2;
export const MIRROR_MAX = 6;

/** Media types the multimodal planner will accept for a pasted image. */
export const ALLOWED_IMAGE_MEDIA_TYPES = [
  "image/png",
  "image/jpeg",
  "image/gif",
  "image/webp",
] as const;
export type ImageMediaType = (typeof ALLOWED_IMAGE_MEDIA_TYPES)[number];

/** At most this many images per prompt, and this many base64 bytes each (~4MB). */
export const MAX_IMAGES_PER_PROMPT = 6;
export const MAX_IMAGE_BASE64_CHARS = 4_000_000;

export type ConsoleImage = { mediaType: ImageMediaType; dataBase64: string };

export type PlanStep = { cmd: string; intent: string };

/**
 * A coarse phase the console UI renders, derived ONLY from the build's real
 * status. The workspace never invents a phase the backend does not report — a
 * console that shows "running" is a console whose ClaudeBuild row says RUNNING.
 */
export type ConsolePhase =
  | "idle" // no build yet
  | "planning" // Claude is drafting / plan queued
  | "awaiting" // plan ready, waiting for the owner to approve
  | "running" // approved plan executing over SSH
  | "done"
  | "failed";

/** Statuses that mean the build has finished (terminal). */
export const TERMINAL_STATUSES = ["DONE", "FAILED"] as const;

/** Map a raw ClaudeBuild.status to the coarse console phase. Null status = idle. */
export function consolePhase(status: string | null | undefined): ConsolePhase {
  switch (status) {
    case "QUEUED":
    case "PLANNING":
      return "planning";
    case "AWAITING_APPROVAL":
      return "awaiting";
    case "RUNNING":
      return "running";
    case "DONE":
      return "done";
    case "FAILED":
      return "failed";
    default:
      return "idle";
  }
}

/** True while a build is neither idle nor terminal (i.e. work is in flight). */
export function isBuildActive(status: string | null | undefined): boolean {
  const phase = consolePhase(status);
  return phase === "planning" || phase === "awaiting" || phase === "running";
}

/* -------------------------------------------------------------------------- */
/* Mirror-mode fan-out                                                         */
/* -------------------------------------------------------------------------- */

export type MirrorBuildRequest = {
  serverId: string;
  prompt: string;
  mirrorGroupId: string;
  title: string;
};

/**
 * Expand one mirror instruction into N independent build requests that share
 * the initial prompt and a common mirrorGroupId. `serverIds` is one entry per
 * console — the SAME server id may repeat (mirror on one box) or differ (mirror
 * across several boxes). Each request is otherwise independent: they plan and
 * run separately, and each still requires its own approval.
 *
 * Throws on an out-of-range fan-out so the caller reports it rather than
 * silently launching the wrong number of builds.
 */
export function mirrorFanout(
  prompt: string,
  serverIds: string[],
  mirrorGroupId: string
): MirrorBuildRequest[] {
  const clean = (prompt ?? "").trim();
  if (!clean) throw new Error("Mirror mode needs a prompt to share across the consoles.");
  if (!mirrorGroupId) throw new Error("Mirror mode needs a group id.");
  if (serverIds.length < MIRROR_MIN || serverIds.length > MIRROR_MAX) {
    throw new Error(`Mirror mode spans ${MIRROR_MIN}-${MIRROR_MAX} consoles.`);
  }
  return serverIds.map((serverId, i) => {
    if (!serverId) throw new Error("Every mirror console needs a target server.");
    return {
      serverId,
      prompt: clean,
      mirrorGroupId,
      // A, B, C … so the relationship is legible in the UI and audit log.
      title: `Variation ${String.fromCharCode(65 + i)}`,
    };
  });
}

/* -------------------------------------------------------------------------- */
/* Multimodal image-part assembly                                             */
/* -------------------------------------------------------------------------- */

/**
 * Parse a browser `data:` URL (as produced by a paste / FileReader) into a
 * validated {mediaType, dataBase64}. Returns null for anything that is not a
 * supported base64 image data URL — the caller drops it rather than forwarding
 * an unknown blob to the model.
 */
export function parseImageDataUrl(dataUrl: string): ConsoleImage | null {
  if (typeof dataUrl !== "string") return null;
  const m = /^data:([a-z0-9.+/-]+);base64,([A-Za-z0-9+/=\s]+)$/i.exec(dataUrl.trim());
  if (!m) return null;
  const mediaType = m[1].toLowerCase();
  if (!(ALLOWED_IMAGE_MEDIA_TYPES as readonly string[]).includes(mediaType)) return null;
  const dataBase64 = m[2].replace(/\s+/g, "");
  if (!dataBase64) return null;
  return { mediaType: mediaType as ImageMediaType, dataBase64 };
}

/** Reject images that are too many or too large before they reach the API. */
export function validateImages(images: ConsoleImage[]): { ok: true } | { ok: false; error: string } {
  if (images.length > MAX_IMAGES_PER_PROMPT) {
    return { ok: false, error: `Attach at most ${MAX_IMAGES_PER_PROMPT} images per message.` };
  }
  for (const img of images) {
    if (!(ALLOWED_IMAGE_MEDIA_TYPES as readonly string[]).includes(img.mediaType)) {
      return { ok: false, error: `Unsupported image type: ${img.mediaType}` };
    }
    if (!img.dataBase64 || img.dataBase64.length > MAX_IMAGE_BASE64_CHARS) {
      return { ok: false, error: "One of the images is too large (max ~4MB each)." };
    }
  }
  return { ok: true };
}

/**
 * An Anthropic Messages-API user-content block: a text block, or a base64 image
 * block. Shape matches the multimodal Messages API exactly (image blocks carry
 * `source: { type: "base64", media_type, data }`).
 */
export type AnthropicTextBlock = { type: "text"; text: string };
export type AnthropicImageBlock = {
  type: "image";
  source: { type: "base64"; media_type: ImageMediaType; data: string };
};
export type AnthropicContentBlock = AnthropicTextBlock | AnthropicImageBlock;

/**
 * Assemble the user-turn content for a plan request: the pasted images first
 * (so the model has the visual context before the instruction), then the text
 * prompt. When there are no images this is a single text block, byte-identical
 * to the plain-text planner path.
 */
export function buildUserContent(prompt: string, images: ConsoleImage[]): AnthropicContentBlock[] {
  const blocks: AnthropicContentBlock[] = [];
  for (const img of images) {
    blocks.push({
      type: "image",
      source: { type: "base64", media_type: img.mediaType, data: img.dataBase64 },
    });
  }
  blocks.push({ type: "text", text: prompt });
  return blocks;
}

/* -------------------------------------------------------------------------- */
/* Plan parsing (shared shape with the worker's plan phase)                    */
/* -------------------------------------------------------------------------- */

/**
 * Parse Claude's plan reply into a validated list of {cmd,intent} steps, or
 * null. Mirrors the worker's parser so a plan produced in-action executes the
 * same way the worker's own plans do. Tolerates prose around the JSON array.
 */
export function parsePlanReply(reply: string): PlanStep[] | null {
  if (typeof reply !== "string") return null;
  const start = reply.indexOf("[");
  const end = reply.lastIndexOf("]");
  if (start === -1 || end === -1 || end < start) return null;
  let raw: unknown;
  try {
    raw = JSON.parse(reply.slice(start, end + 1));
  } catch {
    return null;
  }
  if (!Array.isArray(raw)) return null;
  const steps: PlanStep[] = [];
  for (const item of raw) {
    if (typeof item === "string") {
      const cmd = item.trim();
      if (cmd) steps.push({ cmd, intent: "" });
    } else if (item && typeof item === "object") {
      const anyItem = item as Record<string, unknown>;
      const cmd = String(anyItem.cmd ?? anyItem.command ?? "").trim();
      const intent = String(anyItem.intent ?? anyItem.description ?? "").trim();
      if (cmd) steps.push({ cmd, intent });
    }
  }
  return steps.length ? steps : null;
}

"use server";

// Server actions for the Build Studio multi-console workspace.
//
// EVERY export of a "use server" file is a public network endpoint, so every
// action here authenticates (requireUser) and ownership-checks the server id it
// is handed, INSIDE the function, before doing anything — one customer's console
// must never reach another customer's server.
//
// Flow (chat console, plan-then-approve preserved):
//   planConsoleBuild(serverId, prompt, images[]) — authenticates, ownership-checks,
//     asks Claude (BYOK, MULTIMODAL) for a command plan SYNCHRONOUSLY, stores it,
//     and leaves the build AWAITING_APPROVAL. NOTHING runs on the server here.
//   -> approveBuild(id)  (lib/actions-claude.ts, CAS-guarded) enqueues the worker
//        EXECUTE job, which runs the approved plan over SSH under its denylist.
//   -> rejectBuild(id)   marks it FAILED; nothing runs.
//
// Planning is done in the action (not the worker) so pasted images can be wired
// into the message — the worker's planner is string-only. Execution still goes
// through the existing worker + denylist, so the SSH safety guard is unchanged.

import { db } from "./db";
import { requireUser } from "./auth";
import { effectiveKeyFor } from "./anthropic";
import { serverRootPassword } from "./sftp";
import { getSettingBool } from "./settings";
import {
  buildUserContent,
  parseImageDataUrl,
  parsePlanReply,
  validateImages,
  MAX_CONSOLES,
  type ConsoleImage,
  type AnthropicContentBlock,
} from "./claude-console-core";

const MAX_PROMPT_CHARS = 2000;
const MIN_PROMPT_CHARS = 8;

// A workspace holds up to MAX_CONSOLES consoles, each of which can have a build
// in flight — so the active-build ceiling matches the console ceiling. A short
// window rate-limit keeps a burst (e.g. a 6-way mirror) sane.
const MAX_ACTIVE_CONSOLE_BUILDS = MAX_CONSOLES;
const RATE_WINDOW_MS = 60_000;
const MAX_BUILDS_PER_WINDOW = 12;

// Statuses that mean a build is not yet finished — used for in-flight accounting.
const ACTIVE_STATUSES = ["QUEUED", "PLANNING", "AWAITING_APPROVAL", "RUNNING"] as const;

// Kept in sync with worker/claude.ts CLAUDE_MAX_COMMANDS — the plan is capped to
// the same length the worker will execute.
const CLAUDE_MAX_COMMANDS = 20;

const ANTHROPIC_URL = "https://api.anthropic.com/v1/messages";
const MODEL = "claude-opus-4-8";
// Stay comfortably under a typical 60s reverse-proxy read timeout.
const PLAN_TIMEOUT_MS = 55_000;

const PLAN_SYSTEM_PROMPT = `You are an expert Linux server administrator. You are given a goal for a SINGLE Debian/Ubuntu server that you operate on over SSH as root. The goal may include screenshots or images for context. Produce a PLAN — do NOT run anything.

Output ONLY a JSON array of steps and NOTHING else (no markdown, no backticks, no prose before or after). Each step is an object:
{"cmd": "<one non-interactive shell command>", "intent": "<short plain-English explanation of what it does and why>"}

Rules for the plan:
- Operate ONLY on this one server. Never touch other hosts, networks, or cloud APIs.
- Commands must be non-interactive: use flags like -y and DEBIAN_FRONTEND=noninteractive; never launch editors, pagers, REPLs, or anything that waits for input.
- NON-DESTRUCTIVE ONLY. Absolutely no whole-disk or whole-system operations: no rm -rf /, no mkfs/fdisk/dd on disks, no wiping /etc, no reboot/shutdown/poweroff/halt, no user/password changes, no disabling SSH.
- Keep each command self-contained and idempotent where possible.
- Prefer standard packages and services (apt, systemctl, nginx, ufw, etc.).
- At most ${CLAUDE_MAX_COMMANDS} steps. If the goal cannot be met safely, return an empty array [].`;

/** Multimodal plan request. Never throws to the caller — returns text or throws internally-caught. */
async function callClaudePlan(
  apiKey: string,
  content: AnthropicContentBlock[]
): Promise<string> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), PLAN_TIMEOUT_MS);
  let res: Response;
  try {
    res = await fetch(ANTHROPIC_URL, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
      },
      body: JSON.stringify({
        model: MODEL,
        max_tokens: 4096,
        system: PLAN_SYSTEM_PROMPT,
        messages: [{ role: "user", content }],
      }),
      signal: controller.signal,
    });
  } finally {
    clearTimeout(timer);
  }
  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(`Anthropic API ${res.status}: ${body.slice(0, 300)}`);
  }
  const data = (await res.json()) as { content?: Array<{ type: string; text?: string }> };
  return (data.content ?? [])
    .filter((b) => b.type === "text" && typeof b.text === "string")
    .map((b) => b.text as string)
    .join("")
    .trim();
}

export type PlanConsoleResult = { error?: string; buildId?: string };

/**
 * Plan a build for one console: authenticate, ownership-check the server, ask
 * Claude (with any pasted images) for a command plan, and store it as
 * AWAITING_APPROVAL. Nothing runs on the server. `imageDataUrls` are browser
 * `data:` URLs; unparseable ones are dropped.
 */
export async function planConsoleBuild(
  serverId: string,
  prompt: string,
  imageDataUrls?: string[],
  mirrorGroupId?: string | null,
  title?: string | null
): Promise<PlanConsoleResult> {
  const user = await requireUser();

  // Feature flag: the whole "Build with AI" surface can be switched off.
  if (!(await getSettingBool("feature_claude_builder", true))) {
    return { error: "Build with AI is currently unavailable." };
  }

  const clean = (prompt ?? "").trim();
  if (clean.length < MIN_PROMPT_CHARS) {
    return { error: "Please describe what you'd like to build (a sentence or two)." };
  }
  if (clean.length > MAX_PROMPT_CHARS) {
    return { error: `Prompt is too long (max ${MAX_PROMPT_CHARS} characters).` };
  }

  // Parse + validate any pasted images (drop anything that is not a supported
  // base64 image data URL).
  const images: ConsoleImage[] = [];
  for (const url of imageDataUrls ?? []) {
    const img = parseImageDataUrl(url);
    if (img) images.push(img);
  }
  const imgCheck = validateImages(images);
  if (!imgCheck.ok) return { error: imgCheck.error };

  // BYOK gate: the owner must have an effective key (their own, or a platform fallback).
  const owner = await db.user.findUnique({
    where: { id: user.id },
    select: { anthropicKeyEnc: true },
  });
  const apiKey = effectiveKeyFor(owner);
  if (!apiKey) {
    return { error: "Add your Anthropic API key in Settings to use Build with AI." };
  }

  // Ownership: the server must belong to THIS user. Ownership-checked from the id
  // that was passed in — never a bare findUnique whose result is then trusted.
  const server = await db.server.findFirst({ where: { id: serverId, userId: user.id } });
  if (!server) return { error: "Server not found." };
  if (server.status !== "RUNNING") {
    return { error: "The server must be running to build on it." };
  }
  if (!server.ipAddress || !serverRootPassword(server)) {
    return { error: "This server isn't reachable yet — try again once it finishes provisioning." };
  }

  // Rate + concurrency sanity, scoped to the user.
  const active = await db.claudeBuild.count({
    where: { userId: user.id, status: { in: [...ACTIVE_STATUSES] } },
  });
  if (active >= MAX_ACTIVE_CONSOLE_BUILDS) {
    return { error: `You already have ${MAX_ACTIVE_CONSOLE_BUILDS} builds in flight. Finish or clear some before starting another.` };
  }
  const recent = await db.claudeBuild.count({
    where: { userId: user.id, createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) } },
  });
  if (recent >= MAX_BUILDS_PER_WINDOW) {
    return { error: "Too many builds started just now — please wait a minute and try again." };
  }

  // Ask Claude for the plan (BYOK, multimodal). This is the only external call.
  let reply: string;
  try {
    reply = await callClaudePlan(apiKey, buildUserContent(clean, images));
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e);
    return { error: `Planning failed: ${msg.slice(0, 200)}` };
  }

  const plan = parsePlanReply(reply);
  if (!plan) {
    return { error: "Claude didn't return a usable plan for this goal. Try rephrasing it." };
  }
  const capped = plan.slice(0, CLAUDE_MAX_COMMANDS);

  // Store the build already planned + awaiting approval (approved=false). The
  // worker's plan phase is skipped; approveBuild will enqueue the EXECUTE job.
  const build = await db.claudeBuild.create({
    data: {
      userId: user.id,
      serverId,
      prompt: clean,
      status: "AWAITING_APPROVAL",
      approved: false,
      plan: JSON.stringify(capped),
      mirrorGroupId: mirrorGroupId?.trim() ? mirrorGroupId.trim() : null,
      title: title?.trim() ? title.trim() : null,
    },
  });

  await db.auditLog
    .create({
      data: {
        userId: user.id,
        action: "server.claude_console_plan",
        detail: `${serverId} ${build.id}${images.length ? ` img=${images.length}` : ""}${
          mirrorGroupId ? ` mirror=${mirrorGroupId}` : ""
        }`,
      },
    })
    .catch(() => {});

  return { buildId: build.id };
}

/**
 * Ownership-checked list of the user's recent builds for the workspace's
 * pipeline board / history. Returns only fields the client renders — never a
 * plan or log body.
 */
export async function listConsoleBuilds(limit = 24) {
  const user = await requireUser();
  const rows = await db.claudeBuild.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
    take: Math.min(Math.max(limit, 1), 50),
    select: {
      id: true,
      status: true,
      steps: true,
      prompt: true,
      title: true,
      mirrorGroupId: true,
      createdAt: true,
      server: { select: { hostname: true } },
    },
  });
  return rows.map((r) => ({
    id: r.id,
    status: r.status,
    steps: r.steps,
    prompt: r.prompt,
    title: r.title,
    mirrorGroupId: r.mirrorGroupId,
    createdAt: r.createdAt.toISOString(),
    hostname: r.server.hostname,
  }));
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripCommentsAndStrings } from "./_source-tools.ts";
import {
  consolePhase,
  isBuildActive,
  mirrorFanout,
  parseImageDataUrl,
  validateImages,
  buildUserContent,
  parsePlanReply,
  MAX_IMAGES_PER_PROMPT,
  MAX_IMAGE_BASE64_CHARS,
  MIRROR_MIN,
  MIRROR_MAX,
  type ConsoleImage,
} from "../lib/claude-console-core.ts";

/* ------------------------------------------------------------------ *
 * 1. Console state machine — phase is derived only from real status
 * ------------------------------------------------------------------ */

test("consolePhase maps every build status to a coarse UI phase", () => {
  assert.equal(consolePhase(null), "idle");
  assert.equal(consolePhase(undefined), "idle");
  assert.equal(consolePhase("QUEUED"), "planning");
  assert.equal(consolePhase("PLANNING"), "planning");
  assert.equal(consolePhase("AWAITING_APPROVAL"), "awaiting");
  assert.equal(consolePhase("RUNNING"), "running");
  assert.equal(consolePhase("DONE"), "done");
  assert.equal(consolePhase("FAILED"), "failed");
  // An unknown status is idle, never a fabricated "running"/"done".
  assert.equal(consolePhase("WAT"), "idle");
});

test("isBuildActive is true only for in-flight statuses", () => {
  for (const s of ["QUEUED", "PLANNING", "AWAITING_APPROVAL", "RUNNING"]) {
    assert.equal(isBuildActive(s), true, `${s} should be active`);
  }
  for (const s of ["DONE", "FAILED", null, undefined, "NOPE"]) {
    assert.equal(isBuildActive(s as string), false, `${String(s)} should not be active`);
  }
});

/* ------------------------------------------------------------------ *
 * 2. Mirror-mode fan-out
 * ------------------------------------------------------------------ */

test("mirrorFanout expands one prompt into N independent requests sharing a group", () => {
  const reqs = mirrorFanout("build a landing page", ["s1", "s2", "s3"], "grp1");
  assert.equal(reqs.length, 3);
  assert.deepEqual(reqs.map((r) => r.serverId), ["s1", "s2", "s3"]);
  // All share the initial prompt and the mirror group.
  assert.ok(reqs.every((r) => r.prompt === "build a landing page"));
  assert.ok(reqs.every((r) => r.mirrorGroupId === "grp1"));
  // Titles make the relationship legible.
  assert.deepEqual(reqs.map((r) => r.title), ["Variation A", "Variation B", "Variation C"]);
});

test("mirrorFanout allows the SAME server repeated (mirror on one box)", () => {
  const reqs = mirrorFanout("try two variations", ["s1", "s1"], "grp2");
  assert.equal(reqs.length, 2);
  assert.deepEqual(reqs.map((r) => r.serverId), ["s1", "s1"]);
});

test("mirrorFanout trims the shared prompt", () => {
  const reqs = mirrorFanout("   spaced   ", ["a", "b"], "g");
  assert.ok(reqs.every((r) => r.prompt === "spaced"));
});

test("mirrorFanout refuses out-of-range fan-outs rather than launching the wrong count", () => {
  assert.throws(() => mirrorFanout("x", ["only-one"], "g"), /2-6/);
  const seven = Array.from({ length: MIRROR_MAX + 1 }, (_, i) => `s${i}`);
  assert.throws(() => mirrorFanout("x", seven, "g"), /2-6/);
  // Boundaries are allowed.
  assert.equal(mirrorFanout("x", Array(MIRROR_MIN).fill("s"), "g").length, MIRROR_MIN);
  assert.equal(mirrorFanout("x", Array(MIRROR_MAX).fill("s"), "g").length, MIRROR_MAX);
});

test("mirrorFanout refuses an empty prompt, empty group, or a blank server id", () => {
  assert.throws(() => mirrorFanout("   ", ["a", "b"], "g"), /prompt/);
  assert.throws(() => mirrorFanout("x", ["a", "b"], ""), /group/);
  assert.throws(() => mirrorFanout("x", ["a", ""], "g"), /server/);
});

/* ------------------------------------------------------------------ *
 * 3. Multimodal image-part assembly
 * ------------------------------------------------------------------ */

test("parseImageDataUrl accepts supported base64 image data URLs", () => {
  const png = parseImageDataUrl("data:image/png;base64,iVBORw0KGgo=");
  assert.deepEqual(png, { mediaType: "image/png", dataBase64: "iVBORw0KGgo=" });
  const jpeg = parseImageDataUrl("data:image/jpeg;base64,/9j/4AAQSkZJRg==");
  assert.equal(jpeg?.mediaType, "image/jpeg");
  // Case-insensitive media type, whitespace inside the payload is stripped.
  const withWs = parseImageDataUrl("data:IMAGE/PNG;base64,iVBO Rw0K\nGgo=");
  assert.deepEqual(withWs, { mediaType: "image/png", dataBase64: "iVBORw0KGgo=" });
});

test("parseImageDataUrl rejects non-images and malformed URLs", () => {
  assert.equal(parseImageDataUrl("data:application/pdf;base64,AAAA"), null);
  assert.equal(parseImageDataUrl("data:image/svg+xml;base64,AAAA"), null); // not in allowlist
  assert.equal(parseImageDataUrl("https://example.com/a.png"), null);
  assert.equal(parseImageDataUrl("data:image/png,notbase64"), null);
  assert.equal(parseImageDataUrl(""), null);
  // @ts-expect-error runtime guard for non-strings
  assert.equal(parseImageDataUrl(null), null);
});

test("validateImages enforces count and size caps", () => {
  const ok: ConsoleImage = { mediaType: "image/png", dataBase64: "AAAA" };
  assert.deepEqual(validateImages([ok, ok]), { ok: true });

  const tooMany = Array(MAX_IMAGES_PER_PROMPT + 1).fill(ok);
  assert.equal(validateImages(tooMany).ok, false);

  const tooBig: ConsoleImage = {
    mediaType: "image/png",
    dataBase64: "A".repeat(MAX_IMAGE_BASE64_CHARS + 1),
  };
  assert.equal(validateImages([tooBig]).ok, false);

  const badType = { mediaType: "image/svg+xml", dataBase64: "AAAA" } as unknown as ConsoleImage;
  assert.equal(validateImages([badType]).ok, false);
});

test("buildUserContent puts images before the text prompt in Anthropic block shape", () => {
  const imgs: ConsoleImage[] = [
    { mediaType: "image/png", dataBase64: "AAA" },
    { mediaType: "image/jpeg", dataBase64: "BBB" },
  ];
  const content = buildUserContent("make it look like this", imgs);
  assert.equal(content.length, 3);
  assert.deepEqual(content[0], {
    type: "image",
    source: { type: "base64", media_type: "image/png", data: "AAA" },
  });
  assert.deepEqual(content[1], {
    type: "image",
    source: { type: "base64", media_type: "image/jpeg", data: "BBB" },
  });
  // Text prompt is last.
  assert.deepEqual(content[2], { type: "text", text: "make it look like this" });
});

test("buildUserContent with no images is a single text block", () => {
  const content = buildUserContent("just text", []);
  assert.deepEqual(content, [{ type: "text", text: "just text" }]);
});

/* ------------------------------------------------------------------ *
 * 4. Plan parsing
 * ------------------------------------------------------------------ */

test("parsePlanReply accepts a JSON array of steps, tolerating surrounding prose", () => {
  const reply = 'Here is the plan:\n[{"cmd":"apt-get update","intent":"refresh"}]\nDone.';
  assert.deepEqual(parsePlanReply(reply), [{ cmd: "apt-get update", intent: "refresh" }]);
});

test("parsePlanReply accepts bare command strings and alt keys", () => {
  assert.deepEqual(parsePlanReply('["echo hi"]'), [{ cmd: "echo hi", intent: "" }]);
  assert.deepEqual(parsePlanReply('[{"command":"ls","description":"list"}]'), [
    { cmd: "ls", intent: "list" },
  ]);
});

test("parsePlanReply returns null for empty, non-array, or unparseable replies", () => {
  assert.equal(parsePlanReply("[]"), null);
  assert.equal(parsePlanReply("no json here"), null);
  assert.equal(parsePlanReply('{"cmd":"x"}'), null);
  assert.equal(parsePlanReply("[not json]"), null);
});

/* ------------------------------------------------------------------ *
 * 5. Source-shape tripwire: the new "use server" action is not an
 *    unauthenticated, unscoped endpoint. Every export of a "use server"
 *    file is a public endpoint; this asserts each one authenticates and
 *    ownership-checks, over source stripped of comments AND string
 *    literals (a naive grep matches this repo's own comments/error copy).
 * ------------------------------------------------------------------ */

function actionSource(): string {
  return stripCommentsAndStrings(
    readFileSync(join(import.meta.dirname, "..", "lib", "actions-claude-console.ts"), "utf8")
  );
}

/** Body of `export async function NAME` by brace matching (strings already blanked). */
function bodyOf(src: string, name: string): string {
  const decl = new RegExp(`export\\s+async\\s+function\\s+${name}\\s*\\(`).exec(src);
  assert.ok(decl, `expected an exported action named ${name}`);
  // Walk past the parameter list to the body's opening brace, skipping braces
  // that sit inside a `<...>` return annotation.
  let i = src.indexOf("(", decl.index);
  let parens = 0;
  for (; i < src.length; i++) {
    if (src[i] === "(") parens++;
    else if (src[i] === ")" && --parens === 0) break;
  }
  let angles = 0;
  for (i++; i < src.length; i++) {
    if (src[i] === "<") angles++;
    else if (src[i] === ">") angles = Math.max(0, angles - 1);
    else if (src[i] === "{" && angles === 0) break;
  }
  const start = i;
  let depth = 0;
  for (; i < src.length; i++) {
    if (src[i] === "{") depth++;
    else if (src[i] === "}" && --depth === 0) return src.slice(start, i + 1);
  }
  assert.fail(`unbalanced body for ${name}`);
}

function exportedActions(src: string): string[] {
  return [...src.matchAll(/export\s+async\s+function\s+([A-Za-z0-9_$]+)\s*\(/g)].map((m) => m[1]);
}

test("actions-claude-console declares 'use server' and every export identifies its caller", () => {
  const src = actionSource();
  assert.ok(src.includes('"use server"'), "the module must be a server-action module");
  const names = exportedActions(src);
  assert.ok(names.includes("planConsoleBuild"), "planConsoleBuild must be exported");
  const unguarded = names.filter((n) => !bodyOf(src, n).includes("requireUser("));
  assert.deepEqual(
    unguarded,
    [],
    "these exports are network-reachable by an anonymous caller with no identity check"
  );
});

test("planConsoleBuild ownership-checks the server id it is handed", () => {
  const body = bodyOf(actionSource(), "planConsoleBuild");
  // The server must be resolved user-scoped, not a bare findUnique that is then trusted.
  assert.ok(
    body.includes("userId: user.id"),
    "planConsoleBuild must prove the caller owns the server id before planning on it"
  );
  // BYOK is enforced (no platform key is billed silently without a fallback path).
  assert.ok(body.includes("effectiveKeyFor("), "planConsoleBuild must gate on an effective owner key");
});

test("listConsoleBuilds is scoped to the calling user", () => {
  const body = bodyOf(actionSource(), "listConsoleBuilds");
  assert.ok(body.includes("userId: user.id"), "listConsoleBuilds must only return the caller's builds");
});

