input.content:
"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { planConsoleBuild } from "@/lib/actions-claude-console";
import { approveBuild, rejectBuild } from "@/lib/actions-claude";
import { consolePhase, isBuildActive, type ConsolePhase } from "@/lib/claude-console-core";

/* -------------------------------------------------------------------------- */
/* Types                                                                       */
/* -------------------------------------------------------------------------- */

export type ServerOption = { id: string; hostname: string };

type PlanStep = { cmd: string; intent?: string };

type Turn = {
  key: string;
  prompt: string;
  images: string[]; // data URLs
  buildId: string | null;
  status: string | null; // ClaudeBuild.status
  steps: number;
  log: string;
  plan: string | null; // JSON string of proposed commands
  error: string | null;
};

export type BuildConsoleProps = {
  consoleId: string;
  index: number;
  servers: ServerOption[];
  initialServerId: string;
  /** Mirror mode: a shared prompt auto-sent when the console mounts. */
  autoPrompt?: string;
  mirrorLabel?: string | null;
  onRemove?: () => void;
  canRemove: boolean;
  /** Whether to render compactly (many consoles in a grid). */
  dense?: boolean;
};

/* -------------------------------------------------------------------------- */
/* Web Speech API (voice-to-text) — typed minimally, degrades gracefully.      */
/* -------------------------------------------------------------------------- */

type SpeechRecognitionLike = {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  start: () => void;
  stop: () => void;
  onresult: ((e: { results: ArrayLike<ArrayLike<{ transcript: string }>> }) => void) | null;
  onerror: (() => void) | null;
  onend: (() => void) | null;
};

function getSpeechRecognitionCtor(): (new () => SpeechRecognitionLike) | null {
  if (typeof window === "undefined") return null;
  const w = window as unknown as {
    SpeechRecognition?: new () => SpeechRecognitionLike;
    webkitSpeechRecognition?: new () => SpeechRecognitionLike;
  };
  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
}

/* -------------------------------------------------------------------------- */
/* Helpers                                                                     */
/* -------------------------------------------------------------------------- */

function parsePlan(raw: string | null): PlanStep[] {
  if (!raw) return [];
  try {
    const p = JSON.parse(raw);
    if (Array.isArray(p)) {
      return p
        .map((s) => (typeof s === "string" ? { cmd: s } : { cmd: String(s?.cmd ?? ""), intent: s?.intent }))
        .filter((s) => s.cmd);
    }
  } catch {
    /* ignore */
  }
  return [];
}

const PHASE_TONE: Record<ConsolePhase, string> = {
  idle: "border-white/10 bg-white/5 text-slate-400",
  planning: "border-amber-500/40 bg-amber-500/10 text-amber-300",
  awaiting: "border-sky-500/40 bg-sky-500/10 text-sky-300",
  running: "border-brand-500/40 bg-brand-500/10 text-brand-200",
  done: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300",
  failed: "border-red-500/40 bg-red-500/10 text-red-300",
};

const PHASE_LABEL: Record<ConsolePhase, string> = {
  idle: "idle",
  planning: "planning",
  awaiting: "awaiting approval",
  running: "running",
  done: "done",
  failed: "failed",
};

let seq = 0;
const nextKey = () => `t${Date.now()}_${seq++}`;

/* -------------------------------------------------------------------------- */
/* Component                                                                   */
/* -------------------------------------------------------------------------- */

export function BuildConsole({
  consoleId,
  index,
  servers,
  initialServerId,
  autoPrompt,
  mirrorLabel,
  onRemove,
  canRemove,
  dense = false,
}: BuildConsoleProps) {
  const [serverId, setServerId] = useState(initialServerId || servers[0]?.id || "");
  const [input, setInput] = useState("");
  const [images, setImages] = useState<string[]>([]);
  const [turns, setTurns] = useState<Turn[]>([]);
  const [pending, setPending] = useState(false);
  const [listening, setListening] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const speechSupported = useRef<boolean>(false);
  const autoStarted = useRef(false);

  useEffect(() => {
    speechSupported.current = getSpeechRecognitionCtor() !== null;
  }, []);

  // Auto-scroll the transcript as it grows.
  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [turns]);

  /* ------------------------------ send a plan ----------------------------- */

  const send = useCallback(
    async (promptText: string, imgs: string[]) => {
      const clean = promptText.trim();
      if (clean.length < 8 || !serverId || pending) return;
      setPending(true);
      const key = nextKey();
      setTurns((prev) => [
        ...prev,
        { key, prompt: clean, images: imgs, buildId: null, status: "PLANNING", steps: 0, log: "", plan: null, error: null },
      ]);
      setInput("");
      setImages([]);

      const res = await planConsoleBuild(serverId, clean, imgs, null, null).catch((e) => ({
        error: e instanceof Error ? e.message : "Planning failed.",
      }));
      setTurns((prev) =>
        prev.map((t) =>
          t.key === key
            ? "error" in res && res.error
              ? { ...t, status: "FAILED", error: res.error }
              : { ...t, buildId: (res as { buildId?: string }).buildId ?? null, status: "AWAITING_APPROVAL" }
            : t
        )
      );
      setPending(false);
    },
    [serverId, pending]
  );

  // Mirror mode: fire the shared prompt once, automatically.
  useEffect(() => {
    if (autoStarted.current) return;
    if (autoPrompt && autoPrompt.trim().length >= 8 && serverId) {
      autoStarted.current = true;
      void send(autoPrompt, []);
    }
  }, [autoPrompt, serverId, send]);

  /* ------------------------------- polling -------------------------------- */

  // Poll the most recent turn that has a build id and is still in flight.
  useEffect(() => {
    const active = [...turns].reverse().find((t) => t.buildId && isBuildActive(t.status));
    if (!active?.buildId) return;
    let alive = true;
    let timer: ReturnType<typeof setTimeout>;
    const tick = async () => {
      try {
        const r = await fetch(`/api/claude/${active.buildId}`, { cache: "no-store" });
        if (r.ok) {
          const data = (await r.json()) as { status?: string; steps?: number; log?: string; plan?: string | null };
          if (alive) {
            setTurns((prev) =>
              prev.map((t) =>
                t.buildId === active.buildId
                  ? { ...t, status: data.status ?? t.status, steps: data.steps ?? t.steps, log: data.log ?? t.log, plan: data.plan ?? t.plan }
                  : t
              )
            );
          }
          if (data.status && ["DONE", "FAILED"].includes(data.status)) return;
        }
      } catch {
        /* transient */
      }
      if (alive) timer = setTimeout(tick, 2000);
    };
    void tick();
    return () => {
      alive = false;
      clearTimeout(timer);
    };
  }, [turns]);

  /* -------------------------- approve / reject ---------------------------- */

  const onApprove = useCallback(async (buildId: string) => {
    setTurns((prev) => prev.map((t) => (t.buildId === buildId ? { ...t, status: "QUEUED" } : t)));
    const res = await approveBuild(buildId);
    if (res.error) {
      setTurns((prev) => prev.map((t) => (t.buildId === buildId ? { ...t, status: "FAILED", error: res.error ?? null } : t)));
    }
  }, []);

  const onReject = useCallback(async (buildId: string) => {
    const res = await rejectBuild(buildId);
    if (!res.error) {
      setTurns((prev) => prev.map((t) => (t.buildId === buildId ? { ...t, status: "FAILED", error: "Plan rejected — nothing ran." } : t)));
    }
  }, []);

  /* ----------------------------- images ----------------------------------- */

  const addFiles = useCallback((files: FileList | File[]) => {
    for (const file of Array.from(files)) {
      if (!file.type.startsWith("image/")) continue;
      const reader = new FileReader();
      reader.onload = () => {
        const url = typeof reader.result === "string" ? reader.result : "";
        if (url) setImages((prev) => (prev.length >= 6 ? prev : [...prev, url]));
      };
      reader.readAsDataURL(file);
    }
  }, []);

  const onPaste = useCallback(
    (e: React.ClipboardEvent) => {
      const items = e.clipboardData?.items;
      if (!items) return;
      const files: File[] = [];
      for (const it of Array.from(items)) {
        if (it.kind === "file") {
          const f = it.getAsFile();
          if (f && f.type.startsWith("image/")) files.push(f);
        }
      }
      if (files.length) {
        e.preventDefault();
        addFiles(files);
      }
    },
    [addFiles]
  );

  /* ------------------------------- voice ---------------------------------- */

  const toggleVoice = useCallback(() => {
    const Ctor = getSpeechRecognitionCtor();
    if (!Ctor) return;
    if (listening) {
      recognitionRef.current?.stop();
      return;
    }
    const rec = new Ctor();
    rec.lang = "en-US";
    rec.continuous = false;
    rec.interimResults = false;
    rec.onresult = (ev) => {
      let transcript = "";
      for (let i = 0; i < ev.results.length; i++) transcript += ev.results[i][0].transcript;
      if (transcript) setInput((prev) => (prev ? prev + " " : "") + transcript.trim());
    };
    rec.onerror = () => setListening(false);
    rec.onend = () => setListening(false);
    recognitionRef.current = rec;
    setListening(true);
    try {
      rec.start();
    } catch {
      setListening(false);
    }
  }, [listening]);

  useEffect(() => () => recognitionRef.current?.stop(), []);

  /* ------------------------------- render --------------------------------- */

  const latest = turns[turns.length - 1];
  const phase: ConsolePhase = consolePhase(latest?.status ?? null);
  const server = servers.find((s) => s.id === serverId);
  const busy = pending || isBuildActive(latest?.status ?? null);

  return (
    <div className="flex h-full min-h-0 flex-col overflow-hidden rounded-2xl border border-white/[0.08] bg-navy-900/70 backdrop-blur-md">
      {/* Console header */}
      <div className="flex flex-none items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-3 py-2">
        <span className="flex h-6 w-6 flex-none items-center justify-center rounded-lg bg-brand-500/20 text-[11px] font-bold text-brand-200">
          {index + 1}
        </span>
        <select
          value={serverId}
          onChange={(e) => setServerId(e.target.value)}
          disabled={busy}
          className="min-w-0 flex-1 rounded-lg border border-white/10 bg-white/5 px-2 py-1 text-xs text-white outline-none focus:border-brand-400/60 disabled:opacity-60"
          aria-label="Target server for this console"
        >
          {servers.length === 0 && <option value="">No running servers</option>}
          {servers.map((s) => (
            <option key={s.id} value={s.id} className="bg-navy-900">
              {s.hostname}
            </option>
          ))}
        </select>
        {mirrorLabel && (
          <span className="flex-none rounded-md border border-brand-400/30 bg-brand-500/10 px-1.5 py-0.5 text-[10px] font-semibold text-brand-200" title="Part of a mirror build">
            {mirrorLabel}
          </span>
        )}
        <span className={`flex-none rounded-full border px-2 py-0.5 text-[10px] font-medium ${PHASE_TONE[phase]}`}>
          {busy && phase !== "awaiting" && <span className="mr-1 inline-block h-1.5 w-1.5 animate-pulse rounded-full bg-current align-middle" />}
          {PHASE_LABEL[phase]}
        </span>
        {canRemove && (
          <button
            type="button"
            onClick={onRemove}
            className="flex-none rounded p-1 text-slate-500 hover:bg-white/10 hover:text-white"
            aria-label="Close console"
            title="Close console"
          >
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round">
              <path d="M18 6 6 18M6 6l12 12" />
            </svg>
          </button>
        )}
      </div>

      {/* Transcript */}
      <div ref={scrollRef} className={`min-h-0 flex-1 space-y-3 overflow-y-auto px-3 py-3 ${dense ? "text-[12px]" : "text-[13px]"}`}>
        {turns.length === 0 && (
          <div className="flex h-full flex-col items-center justify-center gap-2 px-4 text-center text-slate-500">
            <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#8a70fb" strokeWidth="1.6" aria-hidden>
              <path d="m4 17 6-6-6-6" />
              <path d="M12 19h8" />
            </svg>
            <p className="text-xs">
              Describe what to build on{" "}
              <span className="font-medium text-slate-300">{server?.hostname ?? "this server"}</span>. Claude proposes a plan; nothing runs until you approve it.
            </p>
          </div>
        )}

        {turns.map((t) => {
          const steps = parsePlan(t.plan);
          const tPhase = consolePhase(t.status);
          return (
            <div key={t.key} className="space-y-2">
              {/* User bubble */}
              <div className="flex justify-end">
                <div className="max-w-[88%] rounded-2xl rounded-br-sm border border-brand-500/30 bg-brand-500/[0.12] px-3 py-2 text-slate-100">
                  {t.images.length > 0 && (
                    <div className="mb-2 flex flex-wrap gap-1.5">
                      {t.images.map((src, i) => (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img key={i} src={src} alt="attachment" className="h-14 w-14 rounded-lg border border-white/10 object-cover" />
                      ))}
                    </div>
                  )}
                  <p className="whitespace-pre-wrap break-words">{t.prompt}</p>
                </div>
              </div>

              {/* Assistant side */}
              {tPhase === "planning" && (
                <div className="flex items-center gap-2 text-slate-400">
                  <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-brand-400" />
                  <span className="text-xs">Drafting a plan…</span>
                </div>
              )}

              {t.error && (
                <div className="rounded-xl border border-red-500/20 bg-red-500/10 px-3 py-2 text-xs text-red-200">{t.error}</div>
              )}

              {tPhase === "awaiting" && steps.length > 0 && t.buildId && (
                <div className="rounded-2xl rounded-bl-sm border border-white/[0.08] bg-navy-950/60 p-3">
                  <p className="mb-2 text-xs font-semibold text-slate-200">Proposed plan · {steps.length} command(s)</p>
                  <ol className="space-y-1.5">
                    {steps.map((s, i) => (
                      <li key={i} className="rounded-lg border border-white/[0.06] bg-black/30 p-2">
                        <code className="block whitespace-pre-wrap break-words font-mono text-[11.5px] text-slate-200">$ {s.cmd}</code>
                        {s.intent && <p className="mt-1 text-[11px] text-slate-500">{s.intent}</p>}
                      </li>
                    ))}
                  </ol>
                  <div className="mt-3 flex items-center gap-2">
                    <button type="button" onClick={() => t.buildId && onApprove(t.buildId)} className="rounded-lg bg-brand-500 px-3 py-1.5 text-xs font-semibold text-white hover:bg-brand-400">
                      Approve &amp; run
                    </button>
                    <button type="button" onClick={() => t.buildId && onReject(t.buildId)} className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-1.5 text-xs font-semibold text-red-200 hover:bg-red-500/20">
                      Reject
                    </button>
                  </div>
                </div>
              )}

              {(tPhase === "running" || tPhase === "done" || tPhase === "failed") && (t.log || tPhase === "running") && (
                <div className="rounded-2xl rounded-bl-sm border border-white/[0.08] bg-navy-950/80">
                  <div className="flex items-center gap-2 border-b border-white/[0.06] px-3 py-1.5">
                    <span className={`h-1.5 w-1.5 rounded-full ${tPhase === "running" ? "animate-pulse bg-brand-400" : tPhase === "done" ? "bg-emerald-400" : "bg-red-500"}`} />
                    <span className="text-[11px] font-medium text-slate-400">
                      {tPhase === "running" ? `running · step ${t.steps}` : tPhase === "done" ? "build complete" : "build failed"}
                    </span>
                  </div>
                  <pre className="max-h-56 overflow-auto whitespace-pre-wrap break-words px-3 py-2 font-mono text-[11px] leading-relaxed text-slate-300">
                    {t.log || "Waiting for the worker to pick up the job…"}
                  </pre>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Composer */}
      <div className="flex-none border-t border-white/[0.06] bg-white/[0.02] p-2.5">
        {images.length > 0 && (
          <div className="mb-2 flex flex-wrap gap-1.5">
            {images.map((src, i) => (
              <div key={i} className="relative">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={src} alt="pending attachment" className="h-12 w-12 rounded-lg border border-white/10 object-cover" />
                <button
                  type="button"
                  onClick={() => setImages((prev) => prev.filter((_, j) => j !== i))}
                  className="absolute -right-1.5 -top-1.5 flex h-4 w-4 items-center justify-center rounded-full bg-navy-950 text-slate-300 ring-1 ring-white/20 hover:text-white"
                  aria-label="Remove image"
                >
                  <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round">
                    <path d="M18 6 6 18M6 6l12 12" />
                  </svg>
                </button>
              </div>
            ))}
          </div>
        )}
        <div className="flex items-end gap-1.5">
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onPaste={onPaste}
            onKeyDown={(e) => {
              if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
                e.preventDefault();
                void send(input, images);
              }
            }}
            placeholder="Describe what to build, or paste an image…  (⌘/Ctrl+Enter to send)"
            rows={dense ? 2 : 2}
            maxLength={2000}
            disabled={!serverId}
            className="min-h-[42px] flex-1 resize-none rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[13px] text-white outline-none placeholder:text-slate-600 focus:border-brand-400/60 disabled:opacity-60"
          />
          <div className="flex flex-none flex-col gap-1.5">
            <div className="flex gap-1.5">
              <input ref={fileInputRef} type="file" accept="image/*" multiple hidden onChange={(e) => e.target.files && addFiles(e.target.files)} />
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="rounded-lg border border-white/10 bg-white/5 p-2 text-slate-300 hover:bg-white/10"
                title="Attach image"
                aria-label="Attach image"
              >
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                  <path d="m21.44 11.05-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48" />
                </svg>
              </button>
              {speechSupported.current && (
                <button
                  type="button"
                  onClick={toggleVoice}
                  className={`rounded-lg border p-2 ${listening ? "border-red-500/40 bg-red-500/15 text-red-300" : "border-white/10 bg-white/5 text-slate-300 hover:bg-white/10"}`}
                  title={listening ? "Stop dictation" : "Dictate (voice to text)"}
                  aria-label="Voice to text"
                >
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3z" />
                    <path d="M19 10v2a7 7 0 0 1-14 0v-2M12 19v3" />
                  </svg>
                </button>
              )}
            </div>
            <button
              type="button"
              onClick={() => void send(input, images)}
              disabled={busy || !serverId || input.trim().length < 8}
              className="rounded-lg bg-brand-500 px-3 py-2 text-xs font-semibold text-white hover:bg-brand-400 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {busy ? "…" : "Send"}
            </button>
          </div>
        </div>
        <p className="mt-1.5 px-0.5 text-[10px] text-slate-500">
          BYOK · plan-then-approve · commands run over SSH only after you approve. Console {consoleId.slice(0, 4)}.
        </p>
      </div>
    </div>
  );
}

