"use client";

import { useMemo, useState } from "react";
import { createPortal } from "react-dom";
import { PageHeader } from "@/components/ui/primitives";
import { BuildConsole, type ServerOption } from "./BuildConsole";
import { PipelineBoard, type BoardBuild } from "./PipelineBoard";
import { mirrorFanout, MAX_CONSOLES, MIRROR_MIN, MIRROR_MAX } from "@/lib/claude-console-core";

/**
 * Build Studio — the multi-console AI build workspace.
 *
 * The name is intentionally isolated in one constant: rename the product by
 * editing WORKSPACE_NAME (and the page metadata) — nothing else depends on it.
 */
export const WORKSPACE_NAME = "Build Studio";

type ConsoleDescriptor = {
  id: string;
  serverId: string;
  autoPrompt?: string;
  mirrorLabel?: string | null;
  mirrorGroupId?: string | null;
  buildTitle?: string | null;
};

let counter = 0;
const newId = () => `c${Date.now()}_${counter++}`;

function gridColsFor(n: number): string {
  if (n <= 1) return "grid-cols-1";
  if (n === 2) return "grid-cols-1 lg:grid-cols-2";
  if (n <= 4) return "grid-cols-1 md:grid-cols-2";
  return "grid-cols-1 md:grid-cols-2 2xl:grid-cols-3";
}

/* -------------------------------------------------------------------------- */
/* Mirror modal                                                                */
/* -------------------------------------------------------------------------- */

function MirrorModal({
  servers,
  onClose,
  onLaunch,
}: {
  servers: ServerOption[];
  onClose: () => void;
  onLaunch: (prompt: string, serverIds: string[]) => void;
}) {
  const [prompt, setPrompt] = useState("");
  const [count, setCount] = useState(Math.min(2, MIRROR_MAX));
  const [targets, setTargets] = useState<string[]>(
    Array.from({ length: MIRROR_MAX }, () => servers[0]?.id ?? "")
  );
  const [error, setError] = useState<string | null>(null);

  const slots = Array.from({ length: count }, (_, i) => i);

  const launch = () => {
    setError(null);
    const serverIds = slots.map((i) => targets[i] || servers[0]?.id || "");
    try {
      // Validate the fan-out with the same pure logic the tests cover.
      mirrorFanout(prompt, serverIds, "preview");
    } catch (e) {
      setError(e instanceof Error ? e.message : "Invalid mirror configuration.");
      return;
    }
    onLaunch(prompt.trim(), serverIds);
  };

  return createPortal(
    <div className="fixed inset-0 z-[60] flex items-start justify-center overflow-y-auto bg-black/70 p-4 backdrop-blur-sm sm:p-8" onClick={onClose}>
      <div className="my-auto w-full max-w-xl overflow-hidden rounded-2xl border border-white/10 bg-navy-900 shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-start justify-between gap-4 border-b border-white/[0.06] p-5">
          <div>
            <h3 className="text-base font-bold text-white">Mirror build</h3>
            <p className="mt-0.5 text-sm text-slate-400">
              Send the same task to {MIRROR_MIN}–{MIRROR_MAX} consoles at once — build it in parallel to compare variations. Each console stays independent and still needs its own approval.
            </p>
          </div>
          <button onClick={onClose} className="rounded-lg p-1.5 text-slate-400 hover:bg-white/10 hover:text-white" aria-label="Close">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <path d="M18 6 6 18M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="space-y-5 p-5">
          <div>
            <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wider text-slate-500">Shared prompt</label>
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="e.g. Build a modern landing page for a coffee shop with a menu and a contact form."
              rows={3}
              maxLength={2000}
              className="w-full resize-y rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none placeholder:text-slate-600 focus:border-brand-400/60"
            />
          </div>

          <div>
            <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wider text-slate-500">How many consoles</label>
            <div className="flex flex-wrap gap-1.5">
              {Array.from({ length: MIRROR_MAX - MIRROR_MIN + 1 }, (_, i) => MIRROR_MIN + i).map((n) => (
                <button
                  key={n}
                  type="button"
                  onClick={() => setCount(n)}
                  className={`h-9 w-9 rounded-lg text-sm font-semibold transition ${count === n ? "bg-brand-500 text-white" : "border border-white/10 bg-white/5 text-slate-300 hover:bg-white/10"}`}
                >
                  {n}
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wider text-slate-500">Target server per console</label>
            <div className="grid gap-2 sm:grid-cols-2">
              {slots.map((i) => (
                <label key={i} className="flex items-center gap-2 rounded-lg border border-white/10 bg-white/5 px-2.5 py-1.5">
                  <span className="flex h-6 w-6 flex-none items-center justify-center rounded-md bg-brand-500/20 text-[11px] font-bold text-brand-200">
                    {String.fromCharCode(65 + i)}
                  </span>
                  <select
                    value={targets[i] ?? ""}
                    onChange={(e) => setTargets((prev) => prev.map((v, j) => (j === i ? e.target.value : v)))}
                    className="min-w-0 flex-1 bg-transparent text-xs text-white outline-none"
                  >
                    {servers.map((s) => (
                      <option key={s.id} value={s.id} className="bg-navy-900">
                        {s.hostname}
                      </option>
                    ))}
                  </select>
                </label>
              ))}
            </div>
            <p className="mt-1.5 text-[11px] text-slate-500">
              Tip: point them at the same server to try variations in place, or at different servers to build in parallel.
            </p>
          </div>

          {error && <p className="text-sm text-red-300">{error}</p>}

          <div className="flex items-center gap-3">
            <button type="button" onClick={launch} disabled={prompt.trim().length < 8} className="btn-primary disabled:cursor-not-allowed disabled:opacity-50">
              Launch {count} consoles
            </button>
            <button type="button" onClick={onClose} className="btn-secondary">
              Cancel
            </button>
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* -------------------------------------------------------------------------- */
/* Workspace                                                                    */
/* -------------------------------------------------------------------------- */

export function BuildStudio({
  servers,
  recentBuilds,
}: {
  servers: ServerOption[];
  recentBuilds: BoardBuild[];
}) {
  const [consoles, setConsoles] = useState<ConsoleDescriptor[]>(() =>
    servers[0] ? [{ id: newId(), serverId: servers[0].id }] : []
  );
  const [mirrorOpen, setMirrorOpen] = useState(false);
  const [showBoard, setShowBoard] = useState(false);

  const atMax = consoles.length >= MAX_CONSOLES;

  const addConsole = () => {
    if (atMax) return;
    setConsoles((prev) => [...prev, { id: newId(), serverId: servers[0]?.id ?? "" }]);
  };

  const removeConsole = (id: string) => setConsoles((prev) => prev.filter((c) => c.id !== id));

  const launchMirror = (prompt: string, serverIds: string[]) => {
    const groupId = `mir_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`;
    // Pure fan-out (unit-tested) produces one descriptor per console.
    const reqs = mirrorFanout(prompt, serverIds, groupId);
    const built: ConsoleDescriptor[] = reqs.map((r, i) => ({
      id: newId(),
      serverId: r.serverId,
      autoPrompt: r.prompt,
      mirrorLabel: `Mirror ${String.fromCharCode(65 + i)}`,
      mirrorGroupId: r.mirrorGroupId,
      buildTitle: r.title,
    }));
    // Mirror replaces the current console set so all N are visible together.
    setConsoles(built);
    setMirrorOpen(false);
  };

  const dense = consoles.length > 2;
  const cols = useMemo(() => gridColsFor(consoles.length), [consoles.length]);

  return (
    <div className="space-y-5">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <PageHeader
          title={WORKSPACE_NAME}
          sub={`Open up to ${MAX_CONSOLES} AI build consoles at once — each an independent chat that plans, you approve, then it configures a server you own. BYOK; nothing runs until you approve.`}
        />
        <div className="flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={() => setShowBoard((v) => !v)}
            className="rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm font-semibold text-slate-200 hover:bg-white/10"
          >
            {showBoard ? "Hide" : "Pipeline"}
          </button>
          <button
            type="button"
            onClick={() => setMirrorOpen(true)}
            disabled={servers.length === 0}
            className="inline-flex items-center gap-1.5 rounded-lg border border-brand-400/30 bg-brand-500/10 px-3 py-2 text-sm font-semibold text-brand-200 hover:bg-brand-500/20 disabled:cursor-not-allowed disabled:opacity-50"
            title="Send one prompt to several consoles at once"
          >
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
              <rect x="3" y="4" width="7" height="16" rx="1.5" />
              <rect x="14" y="4" width="7" height="16" rx="1.5" />
            </svg>
            Mirror build
          </button>
          <button
            type="button"
            onClick={addConsole}
            disabled={atMax || servers.length === 0}
            className="btn-primary disabled:cursor-not-allowed disabled:opacity-50"
            title={atMax ? `Maximum ${MAX_CONSOLES} consoles` : "Open another console"}
          >
            + Console
          </button>
        </div>
      </div>

      {showBoard && <PipelineBoard builds={recentBuilds} />}

      {consoles.length === 0 ? (
        <div className="card p-8 text-center">
          <p className="text-sm text-slate-400">No consoles open.</p>
          <button type="button" onClick={addConsole} disabled={servers.length === 0} className="btn-primary mt-4 disabled:opacity-50">
            Open a console
          </button>
        </div>
      ) : (
        <div className={`grid gap-4 ${cols}`}>
          {consoles.map((c, i) => (
            <div key={c.id} className={consoles.length === 1 ? "h-[560px]" : "h-[480px]"}>
              <BuildConsole
                consoleId={c.id}
                index={i}
                servers={servers}
                initialServerId={c.serverId}
                autoPrompt={c.autoPrompt}
                mirrorLabel={c.mirrorLabel}
                mirrorGroupId={c.mirrorGroupId}
                buildTitle={c.buildTitle}
                canRemove={consoles.length > 1}
                onRemove={() => removeConsole(c.id)}
                dense={dense}
              />
            </div>
          ))}
        </div>
      )}

      {mirrorOpen && <MirrorModal servers={servers} onClose={() => setMirrorOpen(false)} onLaunch={launchMirror} />}
    </div>
  );
}

"use client";

import { consolePhase, type ConsolePhase } from "@/lib/claude-console-core";

/**
 * A lightweight per-project pipeline board.
 *
 * IMPORTANT (this codebase's cardinal rule): every card is placed by the build's
 * REAL, tracked `status` — there is no stage this board reports that the backend
 * does not actually track. The columns are just a view over ClaudeBuild.status
 * (the same field the console polls), so a card in "Running" is a build whose row
 * says RUNNING. Nothing here invents progress it did not verify.
 */

export type BoardBuild = {
  id: string;
  status: string;
  steps: number;
  prompt: string;
  title: string | null;
  mirrorGroupId: string | null;
  createdAt: string;
  hostname: string;
};

// Board stages, each backed one-to-one by a real console phase.
const STAGES: { phase: ConsolePhase; label: string; dot: string }[] = [
  { phase: "planning", label: "Planning", dot: "bg-amber-400" },
  { phase: "awaiting", label: "Awaiting approval", dot: "bg-sky-400" },
  { phase: "running", label: "Running", dot: "bg-brand-400" },
  { phase: "done", label: "Done", dot: "bg-emerald-400" },
  { phase: "failed", label: "Failed", dot: "bg-red-500" },
];

export function PipelineBoard({ builds }: { builds: BoardBuild[] }) {
  // Bucket each build by its real status → phase. "idle" builds (none, in
  // practice) are simply not shown — we never place a card in a stage its
  // status doesn't map to.
  const byPhase = new Map<ConsolePhase, BoardBuild[]>();
  for (const b of builds) {
    const p = consolePhase(b.status);
    if (p === "idle") continue;
    const arr = byPhase.get(p) ?? [];
    arr.push(b);
    byPhase.set(p, arr);
  }

  if (builds.length === 0) {
    return (
      <div className="card p-6 text-center text-sm text-slate-400">
        No builds yet. Start one in a console and it will appear here, tracked by its real status.
      </div>
    );
  }

  return (
    <div className="card p-4">
      <div className="mb-3 flex items-center justify-between">
        <h2 className="text-sm font-semibold text-slate-200">Build pipeline</h2>
        <span className="text-[11px] text-slate-500">Cards reflect each build&apos;s live status.</span>
      </div>
      <div className="grid gap-3 md:grid-cols-3 xl:grid-cols-5">
        {STAGES.map((stage) => {
          const items = byPhase.get(stage.phase) ?? [];
          return (
            <div key={stage.phase} className="rounded-xl border border-white/[0.06] bg-navy-950/50 p-2.5">
              <div className="mb-2 flex items-center gap-1.5 px-0.5">
                <span className={`h-2 w-2 rounded-full ${stage.dot}`} />
                <span className="text-[11px] font-semibold uppercase tracking-wider text-slate-400">{stage.label}</span>
                <span className="ml-auto text-[11px] text-slate-500">{items.length}</span>
              </div>
              <div className="space-y-2">
                {items.length === 0 ? (
                  <p className="px-1 py-2 text-[11px] text-slate-600">—</p>
                ) : (
                  items.map((b) => (
                    <div key={b.id} className="rounded-lg border border-white/[0.06] bg-white/[0.03] p-2">
                      <p className="line-clamp-2 text-[12px] text-slate-200" title={b.prompt}>
                        {b.title ? <span className="font-semibold text-brand-200">{b.title}: </span> : null}
                        {b.prompt}
                      </p>
                      <div className="mt-1.5 flex flex-wrap items-center gap-1.5 text-[10px] text-slate-500">
                        <span className="truncate">{b.hostname}</span>
                        {b.status === "RUNNING" && <span>· step {b.steps}</span>}
                        {b.mirrorGroupId && (
                          <span className="rounded border border-brand-400/30 bg-brand-500/10 px-1 text-brand-200">mirror</span>
                        )}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { platformKeyConfigured } from "@/lib/anthropic";
import { PageHeader, EmptyState } from "@/components/ui/primitives";
import { BuildStudio } from "@/components/customer/claude-code/BuildStudio";
import type { BoardBuild } from "@/components/customer/claude-code/PipelineBoard";

export const dynamic = "force-dynamic";
export const metadata = { title: "Build Studio" };

export default async function BuildPage() {
  const user = await requireUser();

  const [dbUser, servers, builds] = await Promise.all([
    db.user.findUnique({ where: { id: user.id }, select: { anthropicKeyEnc: true } }),
    db.server.findMany({
      where: { userId: user.id, status: "RUNNING" },
      select: { id: true, hostname: true },
      orderBy: { createdAt: "desc" },
    }),
    db.claudeBuild.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 24,
      select: {
        id: true,
        status: true,
        steps: true,
        prompt: true,
        title: true,
        mirrorGroupId: true,
        createdAt: true,
        server: { select: { hostname: true } },
      },
    }),
  ]);

  const keyConnected = Boolean(dbUser?.anthropicKeyEnc);
  // Usable if the customer connected their own key, or a platform fallback exists.
  const usable = keyConnected || platformKeyConfigured();

  const recentBuilds: BoardBuild[] = builds.map((b) => ({
    id: b.id,
    status: b.status,
    steps: b.steps,
    prompt: b.prompt,
    title: b.title,
    mirrorGroupId: b.mirrorGroupId,
    createdAt: b.createdAt.toISOString(),
    hostname: b.server.hostname,
  }));

  if (!usable) {
    return (
      <div className="space-y-6">
        <PageHeader
          title="Build Studio"
          sub="Open several AI build consoles at once — describe what you want, approve the plan, and it configures your servers."
        />
        <div className="card border-amber-500/30 bg-amber-500/[0.06] p-6">
          <h3 className="text-sm font-semibold text-amber-200">Connect a key to get started</h3>
          <p className="mt-1 max-w-xl text-sm text-slate-400">
            Add your Anthropic API key in Settings to enable Build Studio. Everything Claude proposes is shown to you
            for approval before anything runs on your server.
          </p>
          <Link href="/dashboard/settings#anthropic-key" className="btn-primary mt-4 inline-flex">
            Add your API key
          </Link>
        </div>
      </div>
    );
  }

  if (servers.length === 0) {
    return (
      <div className="space-y-6">
        <PageHeader
          title="Build Studio"
          sub="Open several AI build consoles at once — describe what you want, approve the plan, and it configures your servers."
        />
        <EmptyState
          title="No running servers"
          sub="Build Studio builds on a running server. Start or deploy one, then come back here."
          action={
            <Link href="/dashboard/servers" className="btn-primary">
              Go to servers
            </Link>
          }
        />
      </div>
    );
  }

  return <BuildStudio servers={servers} recentBuilds={recentBuilds} />;
}

